mapper.update:
update knowledge_document
set index_status = 'INDEXING',
    error_message = null,
    updated_at = #{updatedAt}
where id = #{id}

update knowledge_document
set index_status = #{indexStatus},
    error_message = #{errorMessage},
    updated_at = #{updatedAt}
where id = #{id}

mapper.select:
select id, knowledge_base_id, document_name, object_key, file_size, version, index_status, chunk_count, vector_dim, error_message, indexed_at, created_at, updated_at from knowledge_document
and knowledge_base_id = #{knowledgeBaseId}
and document_name like concat('%', #{documentName}, '%')
and index_status = #{indexStatus}
order by id desc

select count(1)
from knowledge_document
where knowledge_base_id = #{knowledgeBaseId}
